ure) Contains information about a column in the current table for the query engine to consider. name -&gt; (string) The name of the column for which the other fields in this object apply. Constraints: • min: 1 • max: 127 description -&gt; (string) A description of the column that helps the query engine understand the contents of the column. Constraints: • min: 1 • max: 200 inclusion -&gt; (string) Specifies whether to include or exclude the column during query generation. If you specify EXCLUDE , the column will be ignored. If you specify INCLUDE , all other columns in the table will be ignored. Possible values: • INCLUDE • EXCLUDE curatedQueries -&gt; (list) An array of objects, each of which defines information about example queries to help the query engine generate appropriate SQL queries. Constraints: • min: 0 • max: 10 (structure) Contains configurations for a query, each of which defines information about example queries to help the query engine generate appropriate SQL queries. naturalLanguage -&gt; (string) [required] An example natural language query. Constraints: • min: 1 • max: 1000 sql -&gt; (string) [required] The SQL equivalent of the natural language query. Constraints: • min: 1 • max: 1000 JSON Syntax: { "type": "VECTOR"|"KENDRA"|"SQL"|"MANAGED", "vectorKnowledgeBaseConfiguration": { "embeddingModelArn": "string", "embeddingModelConfiguration": { "bedrockEmbeddingModelConfiguration": { "dimensions": integer, "embeddingDataType": "FLOAT32"|"BINARY", "audio": [ { "segmentationConfiguration": { "fixedLengthDuration": integer } } ... ], "video": [ { "segmentationConfiguration": { "fixedLengthDuration": integer } } ... ], "modelConfiguration": {...} } }, "supplementalDataStorageConfiguration": { "storageLocations": [ { "type": "S3", "s3Location": { "uri": "string" } } ... ] } }, "managedKnowledgeBaseConfiguration": { "embeddingModelType": "CUSTOM"|"MANAGED", "embeddingModelArn": "string", "embeddingModelConfiguration": { "bedrockEmbeddingModelConfiguration": { "dimensions": integer, "embeddingDataType": "FLOAT32"|"BINARY", "audio": [ { "segmentationConfiguration": { "fixedLengthDuration": integer } } ... ], "video": [ { "segmentationConfiguration": { "fixedLengthDuration": integer } } ... ], "modelConfiguration": {...} } }, "serverSideEncryptionConfiguration": { "kmsKeyArn": "string" }, "supplementalDataStorageConfiguration": { "storageLocations": [ { "type": "S3", "s3Location": { "uri": "string" } } ... ] } }, "kendraKnowledgeBaseConfiguration": { "kendraIndexArn": "string" }, "sqlKnowledgeBaseConfiguration": { "type": "REDSHIFT", "redshiftConfiguration": { "storageConfigurations": [ { "type": "REDSHIFT"|"AWS_DATA_CATALOG", "awsDataCatalogConfiguration": { "tableNames": ["string", ...] }, "redshiftConfiguration": { "databaseName": "string" } } ... ], "queryEngineConfiguration": { "type": "SERVERLESS"|"PROVISIONED", "serverlessConfiguration": { "workgroupArn": "string", "authConfiguration": { "type": "IAM"|"USERNAME_PASSWORD", "usernamePasswordSecretArn": "string" } }, "provisionedConfiguration": { "clusterIdentifier": "string", "authConfiguration": { "type": "IAM"|"USERNAME_PASSWORD"|"USERNAME", "databaseUser": "string", "usernamePasswordSecretArn": "string" } } }, "queryGenerationConfiguration": { "executionTimeoutSeconds": integer, "generationContext": { "tables": [ { "name": "string", "description": "string", "inclusion": "INCLUDE"|"EXCLUDE", "columns": [ { "name": "string", "description": "string", "inclusion": "INCLUDE"|"EXCLUDE" } ... ] } ... ], "curatedQueries": [ { "naturalLanguage": "string", "sql": "string" } ... ] } } } } }
